"""
Language detection for URL segments: the scoring helper plus the CLDR-derived
language code set it checks (from babel 2.18, no longer a dependency).
"""


def langcodes_score(language: str, segment: str) -> int:
    "Score a URL segment as a language cue: +1 matching locale, -1 mismatching, 0 unrecognized."
    lang = segment.replace("_", "-").partition("-")[0].lower()
    if lang not in ISO_LANGS:
        return 0
    return 1 if lang == language else -1


# ISO 639-1 language codes accepted by CLDR (167 codes).
# Generated by: all ab where Locale.parse(ab) succeeds in babel 2.18.
ISO_LANGS = frozenset(
    """
    aa ab af ak am an ar as az ba be bg bh bm bn bo br bs ca ce co cs cu cv cy da de dv
    dz ee el en eo es et eu fa ff fi fo fr fy ga gd gl gn gu gv ha he hi hr ht hu hy ia
    id ie ig ii in io is it iu iw ja ji jv jw ka ki kk kl km kn ko ks ku kw ky la lb lg
    ln lo lt lu lv mg mi mk ml mn mo mr ms mt my nb nd ne nl nn no nr nv ny oc om or os
    pa pl ps pt qu rm rn ro ru rw sa sc sd se sg si sk sl sn so sq sr ss st su sv sw ta
    te tg th ti tk tl tn to tr ts tt tw ug uk ur uz ve vi vo wa wo xh yi yo za zh zu
    """.split()
)
